// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@chainlink/contracts/src/v0.8/vrf/interfaces/VRFCoordinatorV2Interface.sol";

/**
 * @title VRFCoordinatorV2Mock
 * @dev Industry-standard VRF Coordinator mock for testing, based on Chainlink's design
 */
contract VRFCoordinatorV2Mock is VRFCoordinatorV2Interface {
    uint96 public constant BASE_FEE = 0.25 ether;
    uint96 public constant GAS_PRICE_LINK = 1e9; // 0.000000001 LINK per gas

    uint256 internal requestIdCounter = 1;
    uint256 internal subscriptionIdCounter = 1;
    mapping(uint256 => address) public requestIdToSender;
    mapping(uint256 => uint256) public requestIdToRequestCommitment;

    // Subscription management (supporting both uint64 and uint256)
    mapping(uint256 => address) public subscriptionOwners;
    mapping(uint256 => address[]) public subscriptionConsumers;
    mapping(uint256 => uint96) public subscriptionBalances;

    event RandomWordsRequested(
        bytes32 indexed keyHash,
        uint256 requestId,
        uint256 preSeed,
        uint64 indexed subId,
        uint16 minimumRequestConfirmations,
        uint32 callbackGasLimit,
        uint32 numWords,
        address indexed sender
    );

    event RandomWordsFulfilled(
        uint256 indexed requestId,
        uint256[] randomWords
    );

    function requestRandomWords(
        bytes32 keyHash,
        uint64 subId,
        uint16 minimumRequestConfirmations,
        uint32 callbackGasLimit,
        uint32 numWords
    ) external override returns (uint256 requestId) {
        requestId = requestIdCounter++;
        requestIdToSender[requestId] = msg.sender;

        uint256 requestCommitment = uint256(keccak256(abi.encode(
            keyHash,
            msg.sender,
            subId,
            requestIdCounter,
            minimumRequestConfirmations,
            callbackGasLimit,
            numWords
        )));
        requestIdToRequestCommitment[requestId] = requestCommitment;

        emit RandomWordsRequested(
            keyHash,
            requestId,
            0, // preSeed
            subId,
            minimumRequestConfirmations,
            callbackGasLimit,
            numWords,
            msg.sender
        );

        return requestId;
    }

    /**
     * @dev Extended requestRandomWords for uint256 subscription ID support
     */
    function requestRandomWords(
        bytes32 keyHash,
        uint256 subId,
        uint16 minimumRequestConfirmations,
        uint32 callbackGasLimit,
        uint32 numWords
    ) external returns (uint256 requestId) {
        requestId = requestIdCounter++;
        requestIdToSender[requestId] = msg.sender;

        uint256 requestCommitment = uint256(keccak256(abi.encode(
            keyHash,
            msg.sender,
            subId,
            requestIdCounter,
            minimumRequestConfirmations,
            callbackGasLimit,
            numWords
        )));
        requestIdToRequestCommitment[requestId] = requestCommitment;

        emit RandomWordsRequested(
            keyHash,
            requestId,
            0, // preSeed
            uint64(subId), // Cast for event compatibility
            minimumRequestConfirmations,
            callbackGasLimit,
            numWords,
            msg.sender
        );

        return requestId;
    }

    /**
     * @dev Fulfill a randomness request for testing
     * @param requestId The request ID to fulfill
     * @param randomWords Array of random words to return
     */
    function fulfillRandomWords(uint256 requestId, uint256[] memory randomWords) external {
        address sender = requestIdToSender[requestId];
        require(sender != address(0), "nonexistent request");
        require(requestIdToRequestCommitment[requestId] != 0, "already fulfilled");

        // Clear the request commitment
        delete requestIdToRequestCommitment[requestId];
        delete requestIdToSender[requestId];

        // Call the consumer's fulfillRandomWords function
        (bool success,) = sender.call(
            abi.encodeWithSignature("fulfillRandomWords(uint256,uint256[])", requestId, randomWords)
        );
        require(success, "callback failed");

        emit RandomWordsFulfilled(requestId, randomWords);
    }

    /**
     * @dev Fulfill a randomness request with deterministic randomness for testing
     * @param requestId The request ID to fulfill
     * @param seed Seed for generating deterministic randomness
     */
    function fulfillRandomWordsWithSeed(uint256 requestId, uint256 seed) external {
        uint256[] memory randomWords = new uint256[](1);
        randomWords[0] = uint256(keccak256(abi.encode(seed, requestId, block.timestamp)));
        this.fulfillRandomWords(requestId, randomWords);
    }

    // Implementation of VRFCoordinatorV2Interface functions

    function getRequestConfig() external pure override returns (uint16, uint32, bytes32[] memory) {
        bytes32[] memory keyHashes = new bytes32[](1);
        keyHashes[0] = 0x474e34a077df58807dbe9c96d3c009b23b3c6d0cce433e59bbf5b34f823bc56c;
        return (3, 500000, keyHashes);
    }

    function createSubscription() external override returns (uint64 subId) {
        subId = uint64(subscriptionIdCounter++);
        subscriptionOwners[subId] = msg.sender;
        return subId;
    }

    function getSubscription(uint64 subId) external view override returns (
        uint96 balance,
        uint64 reqCount,
        address owner,
        address[] memory consumers
    ) {
        return (
            subscriptionBalances[subId],
            0, // reqCount - simplified for testing
            subscriptionOwners[subId],
            subscriptionConsumers[subId]
        );
    }

    function requestSubscriptionOwnerTransfer(uint64 subId, address newOwner) external override {
        require(subscriptionOwners[subId] == msg.sender, "Not the owner");
        // In real implementation, this would be a two-step process
        subscriptionOwners[subId] = newOwner;
    }

    function acceptSubscriptionOwnerTransfer(uint64 subId) external override {
        // Simplified for testing - in real implementation, this completes the transfer
        subscriptionOwners[subId] = msg.sender;
    }

    function addConsumer(uint64 subId, address consumer) external override {
        require(subscriptionOwners[subId] == msg.sender, "Not the owner");
        subscriptionConsumers[subId].push(consumer);
    }

    function removeConsumer(uint64 subId, address consumer) external override {
        require(subscriptionOwners[subId] == msg.sender, "Not the owner");
        address[] storage consumers = subscriptionConsumers[subId];
        for (uint i = 0; i < consumers.length; i++) {
            if (consumers[i] == consumer) {
                consumers[i] = consumers[consumers.length - 1];
                consumers.pop();
                break;
            }
        }
    }

    function cancelSubscription(uint64 subId, address to) external override {
        require(subscriptionOwners[subId] == msg.sender, "Not the owner");
        // Transfer any remaining balance
        uint96 balance = subscriptionBalances[subId];
        if (balance > 0) {
            subscriptionBalances[subId] = 0;
            // In real implementation, this would transfer LINK tokens
        }
        delete subscriptionOwners[subId];
        delete subscriptionConsumers[subId];
    }

    function pendingRequestExists(uint64 subId) external view override returns (bool) {
        // For testing, we'll check if any requests are pending for this subscription
        // This is a simplified implementation
        return subscriptionOwners[subId] != address(0);
    }

    /**
     * @dev Check if a specific request exists and is pending (additional testing function)
     */
    function requestExists(uint256 requestId) external view returns (bool) {
        return requestIdToRequestCommitment[requestId] != 0;
    }

    /**
     * @dev Helper function to set up subscriptions for testing
     */
    function createSubscriptionWithId(uint256 subId, address owner, uint96 balance) external {
        subscriptionOwners[subId] = owner;
        subscriptionBalances[subId] = balance;
    }

    /**
     * @dev Helper function to add consumer to subscription for testing
     */
    function addConsumerToSubscription(uint256 subId, address consumer) external {
        subscriptionConsumers[subId].push(consumer);
    }

    /**
     * @dev Extended getSubscription for uint256 support
     */
    function getSubscription(uint256 subId) external view returns (
        uint96 balance,
        uint64 reqCount,
        address owner,
        address[] memory consumers
    ) {
        return (
            subscriptionBalances[subId],
            0, // reqCount - simplified for testing
            subscriptionOwners[subId],
            subscriptionConsumers[subId]
        );
    }

}

contracts/MyNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/interfaces/IERC4906.sol";

contract MyNFT is ERC721URIStorage, ERC2981, Ownable {
    uint256 private _tokenIdCounter;
    uint256 public mintPrice = 0;

    // Pass msg.sender as the initial owner to Ownable constructor
    constructor() ERC721("MyNFTCollection", "MNC") Ownable(msg.sender) {
    // Set default royalty: 5% to contract owner
      _setDefaultRoyalty(msg.sender, 500); // 500 = 5% (denominator is 10000)
    }

    function mintNFT(address to, string memory tokenURI) public payable returns (uint256) {
        require(msg.value >= mintPrice, "Insufficient payment");
        uint256 tokenId = _tokenIdCounter;
        _tokenIdCounter++;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, tokenURI);
        return tokenId;
    }

    function totalSupply() public view returns (uint256) {
        return _tokenIdCounter;
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721URIStorage, ERC2981)
        returns (bool)
    {
        return interfaceId == type(IERC4906).interfaceId || // ERC4906 interface ID
               super.supportsInterface(interfaceId);
    }

    function setRoyaltyInfo(address receiver, uint96 feeNumerator) external onlyOwner {
        _setDefaultRoyalty(receiver, feeNumerator);
    }

    /**
     * @dev Updates the metadata URI for a token and emits MetadataUpdate event
     * @param tokenId The token ID to update
     * @param newTokenURI The new metadata URI
     */
    function updateTokenURI(uint256 tokenId, string memory newTokenURI) external onlyOwner {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        _setTokenURI(tokenId, newTokenURI);
        emit MetadataUpdate(tokenId);
    }

    /**
     * @dev Batch update metadata for multiple tokens
     * @param fromTokenId Starting token ID  
     * @param toTokenId Ending token ID
     */
    function batchUpdateMetadata(uint256 fromTokenId, uint256 toTokenId) external onlyOwner {
        require(fromTokenId <= toTokenId, "Invalid range");
        emit BatchMetadataUpdate(fromTokenId, toTokenId);
    }
}

contracts/MysteryBox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@chainlink/contracts/src/v0.8/vrf/interfaces/VRFCoordinatorV2Interface.sol";

// Interface for the main MyNFT contract
interface IMyNFT {
    function mintNFT(address to, string memory tokenURI) external returns (uint256);
}

/**
 * @title MysteryBox
 * @dev Industry-level lootbox contract for NFT ticketing, using Chainlink VRF and UUPS upgradability.
 */
contract MysteryBox is UUPSUpgradeable, OwnableUpgradeable {
    // Chainlink VRF variables
    VRFCoordinatorV2Interface public COORDINATOR;
    uint256 public vrfSubscriptionId; // uint256 for VRF v2.5 compatibility
    bytes32 public vrfKeyHash;
    uint32 public vrfCallbackGasLimit;
    uint16 public vrfRequestConfirmations;
    uint32 public vrfNumWords;

    // Prize pool: array of available prize URIs
    string[] private prizeURIs;
    // Mapping to track which prizes are still available
    mapping(uint256 => bool) private isPrizeAvailable;
    // Number of prizes remaining
    uint256 public prizesRemaining;

    // Box price (editable by owner)
    uint256 public boxPrice;

    // MyNFT contract
    address public myNFTAddress;
    IMyNFT public myNFT;

    // Box counter
    uint256 private _boxId;
    // Mapping requestId to opener info
    struct OpenRequest {
        address user;
        uint256 boxId;
    }
    mapping(uint256 => OpenRequest) public openRequests;

    // Events
    event BoxPurchased(address indexed user, uint256 boxId);
    event BoxOpened(address indexed user, uint256 boxId, uint256 prizeTokenId, string prizeURI);
    event PrizeAdded(string prizeURI);
    event PrizeRemoved(string prizeURI);
    event BoxPriceUpdated(uint256 newPrice);
    event Withdraw(address indexed to, uint256 amount);
    event SubscriptionIdUpdated(uint256 oldSubId, uint256 newSubId);
    event VRFConfigUpdated(bytes32 keyHash, uint32 callbackGasLimit, uint16 requestConfirmations);

    //  Initializer (replaces constructor for upgradeable contracts) 
    function initialize(
        address _myNFTAddress,
        address _vrfCoordinator,
        uint256 _vrfSubscriptionId,
        bytes32 _vrfKeyHash,
        uint32 _vrfCallbackGasLimit,
        uint16 _vrfRequestConfirmations
    ) public initializer {
        __Ownable_init(msg.sender);
        __UUPSUpgradeable_init();
        COORDINATOR = VRFCoordinatorV2Interface(_vrfCoordinator);
        vrfSubscriptionId = _vrfSubscriptionId;
        vrfKeyHash = _vrfKeyHash;
        vrfCallbackGasLimit = _vrfCallbackGasLimit;
        vrfRequestConfirmations = _vrfRequestConfirmations;
        vrfNumWords = 1;
        myNFTAddress = _myNFTAddress;
        myNFT = IMyNFT(_myNFTAddress);
        boxPrice = 0.01 ether; // Default price, editable by owner

        // Validate subscription exists using low-level call for uint256 support
        (bool success, bytes memory data) = address(COORDINATOR).staticcall(
            abi.encodeWithSignature("getSubscription(uint256)", _vrfSubscriptionId)
        );
        if (success) {
            (uint96 balance, , address owner, ) = abi.decode(data, (uint96, uint64, address, address[]));
            require(owner != address(0), "Invalid VRF subscription ID");
        } else {
            // Fallback to standard getSubscription if coordinator doesn't support uint256
            revert("VRF coordinator doesn't support large subscription IDs");
        }
    }

    // Prize Pool Management (This is owner only) 
    function addPrizeURI(string memory uri) external onlyOwner {
        prizeURIs.push(uri);
        isPrizeAvailable[prizeURIs.length - 1] = true;
        prizesRemaining++;
        emit PrizeAdded(uri);
    }

    function removePrize(uint256 index) external onlyOwner {
        require(index < prizeURIs.length, "Invalid index");
        require(isPrizeAvailable[index], "Already removed");
        isPrizeAvailable[index] = false;
        prizesRemaining--;
        emit PrizeRemoved(prizeURIs[index]);
    }

    function getPrizeURIs() external view returns (string[] memory) {
        return prizeURIs;
    }

    //  Box Price Management (owner only) 
    function setBoxPrice(uint256 newPrice) external onlyOwner {
        boxPrice = newPrice;
        emit BoxPriceUpdated(newPrice);
    }

    //  Box Purchase & Opening 
    function purchaseAndOpenBox() external payable returns (uint256) {
        require(msg.value >= boxPrice, "Insufficient payment");
        require(prizesRemaining > 0, "No prizes left");

        // Check subscription status before making VRF request (uint256 support)
        (bool success, bytes memory data) = address(COORDINATOR).staticcall(
            abi.encodeWithSignature("getSubscription(uint256)", vrfSubscriptionId)
        );
        require(success, "Failed to get subscription info");
        (uint96 balance, , address owner, address[] memory consumers) = abi.decode(data, (uint96, uint64, address, address[]));
        require(balance > 0, "VRF subscription not funded");
        require(owner != address(0), "VRF subscription does not exist");

        // Check if this contract is a consumer (optional but recommended)
        bool isConsumer = false;
        for (uint i = 0; i < consumers.length; i++) {
            if (consumers[i] == address(this)) {
                isConsumer = true;
                break;
            }
        }
        require(isConsumer, "Contract not registered as VRF consumer");

        uint256 boxId = _boxId++;
        emit BoxPurchased(msg.sender, boxId);

        // Request randomness from Chainlink VRF using low-level call for uint256 support
        (bool vrfSuccess, bytes memory vrfData) = address(COORDINATOR).call(
            abi.encodeWithSignature(
                "requestRandomWords(bytes32,uint256,uint16,uint32,uint32)",
                vrfKeyHash,
                vrfSubscriptionId,
                vrfRequestConfirmations,
                vrfCallbackGasLimit,
                vrfNumWords
            )
        );
        require(vrfSuccess, "VRF request failed");
        uint256 requestId = abi.decode(vrfData, (uint256));
        openRequests[requestId] = OpenRequest({user: msg.sender, boxId: boxId});
        return boxId;
    }

    // Only allow the VRF coordinator to call fulfillRandomWords
    modifier onlyVRFCoordinator() {
        require(msg.sender == address(COORDINATOR), "Only VRFCoordinator can fulfill");
        _;
    }

    //  Chainlink VRF Callback 
    function fulfillRandomWords(uint256 requestId, uint256[] memory randomWords) external onlyVRFCoordinator {
        OpenRequest memory req = openRequests[requestId];
        require(req.user != address(0), "Invalid request");
        require(prizesRemaining > 0, "No prizes left");
        // Find a random available prize
        uint256 availableCount = prizesRemaining;
        uint256 rand = randomWords[0] % availableCount;
        uint256 index = 0;
        uint256 found = 0;
        for (uint256 i = 0; i < prizeURIs.length; i++) {
            if (isPrizeAvailable[i]) {
                if (found == rand) {
                    index = i;
                    break;
                }
                found++;
            }
        }
        // Mark prize as used
        isPrizeAvailable[index] = false;
        prizesRemaining--;
        string memory prizeURI = prizeURIs[index];
        // Mint the prize NFT to the user
        uint256 prizeTokenId = myNFT.mintNFT(req.user, prizeURI);
        emit BoxOpened(req.user, req.boxId, prizeTokenId, prizeURI);
        delete openRequests[requestId];
    }

    //  Emergency & Admin Functions 
    function withdraw(address payable to) external onlyOwner {
        uint256 bal = address(this).balance;
        require(bal > 0, "No balance");
        to.transfer(bal);
        emit Withdraw(to, bal);
    }

    function setMyNFTAddress(address _myNFTAddress) external onlyOwner {
        myNFTAddress = _myNFTAddress;
        myNFT = IMyNFT(_myNFTAddress);
    }

    //  VRF Subscription Management 
    function setSubscriptionId(uint256 newSubId) external onlyOwner {
        // Validate new subscription exists using low-level call for uint256 support
        (bool success, bytes memory data) = address(COORDINATOR).staticcall(
            abi.encodeWithSignature("getSubscription(uint256)", newSubId)
        );
        require(success, "Failed to get subscription info");
        (uint96 balance, , address owner, ) = abi.decode(data, (uint96, uint64, address, address[]));
        require(owner != address(0), "Subscription does not exist");

        uint256 oldSubId = vrfSubscriptionId;
        vrfSubscriptionId = newSubId;
        emit SubscriptionIdUpdated(oldSubId, newSubId);
    }

    function updateVRFConfig(
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        uint16 _requestConfirmations
    ) external onlyOwner {
        require(_callbackGasLimit >= 20000 && _callbackGasLimit <= 2500000, "Invalid gas limit");
        require(_requestConfirmations >= 3 && _requestConfirmations <= 200, "Invalid confirmations");

        vrfKeyHash = _keyHash;
        vrfCallbackGasLimit = _callbackGasLimit;
        vrfRequestConfirmations = _requestConfirmations;

        emit VRFConfigUpdated(_keyHash, _callbackGasLimit, _requestConfirmations);
    }

    function getSubscriptionInfo() external view returns (
        uint96 balance,
        uint64 reqCount,
        address owner,
        address[] memory consumers
    ) {
        // Use low-level call for uint256 subscription ID support
        (bool success, bytes memory data) = address(COORDINATOR).staticcall(
            abi.encodeWithSignature("getSubscription(uint256)", vrfSubscriptionId)
        );
        require(success, "Failed to get subscription info");
        return abi.decode(data, (uint96, uint64, address, address[]));
    }

    function isConsumerRegistered() external view returns (bool) {
        (bool success, bytes memory data) = address(COORDINATOR).staticcall(
            abi.encodeWithSignature("getSubscription(uint256)", vrfSubscriptionId)
        );
        if (!success) return false;

        (, , , address[] memory consumers) = abi.decode(data, (uint96, uint64, address, address[]));
        for (uint i = 0; i < consumers.length; i++) {
            if (consumers[i] == address(this)) {
                return true;
            }
        }
        return false;
    }

    //  UUPS Authorization 
    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    //  Required by Solidity for VRFConsumerBaseV2 
    receive() external payable {}
    fallback() external payable {}
}

